#!/usr/bin/env node
/**
 * Shared fixtures for the Apple ports of three TypeScript modules, generated by
 * RUNNING the TypeScript, so the Swift tests assert equality with the real
 * implementation rather than with someone's reading of it:
 *
 * - `routeShape` (src/lib/analytics/events.ts, mirrored by
 *   mobile/src/lib/analytics.ts) -> route-shape.json
 * - `noteDocumentToMarkdown` (mobile/src/features/notes/noteMarkdownExport.ts)
 *   -> note-markdown.json
 * - `buildNoteTemplate` (mobile/src/features/notes/noteTemplates.ts)
 *   -> note-templates.json
 *
 * Run from the repo root, with the time zone pinned because the templates
 * format local dates:
 *
 *   TZ=UTC node --experimental-strip-types macos/scripts/generate-port-fixtures.mjs
 *
 * and commit the output under macos/SureWord-iOSTests/Fixtures/.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { routeShape } from "../../src/lib/analytics/events.ts";
import { noteDocumentToMarkdown } from "../../mobile/src/features/notes/noteMarkdownExport.ts";
import { buildNoteTemplate } from "../../mobile/src/features/notes/noteTemplates.ts";

if (new Date(0).getTimezoneOffset() !== 0) {
	console.error("Run with TZ=UTC: the template dates are local-time.");
	process.exit(1);
}

const out = join(dirname(fileURLToPath(import.meta.url)), "../SureWord-iOSTests/Fixtures");
mkdirSync(out, { recursive: true });
const write = (name, value) => writeFileSync(join(out, name), `${JSON.stringify(value, null, "\t")}\n`);

// ---------------------------------------------------------------- routeShape
const paths = [
	"/api/notes",
	"/api/notes?summary=1",
	"/api/verse-of-day/audio",
	"/api/conversations/cmfk3x9q10001l504abcd1234/messages/cmfk3x9q10002l504efgh5678",
	"/api/learn/0f8a1b2c-3d4e-5f60-7182-93a4b5c6d7e8/review",
	"/api/learn/0F8A1B2C-3D4E-5F60-7182-93A4B5C6D7E8",
	"/api/reading-plans/12/days/3",
	"https://sureword.app/api/ask-question",
	"https://sureword.app/api/notes/cm1234567890abcd?x=1#frag",
	"/api/get-verse?ref=John+3:16",
	"/api/church/search?q=first+baptist",
	"/api/shared/abc",
	"/shared/plainword",
	"/api/shared/9f8a7b6c5d4e/comments",
	"/api/notes/user_2abcDEF123",
	"/api/notes/short1",
	"/api/notes/verse-of-the-day-2026",
	"/api/notes/abcdefghijklmnop",
	"/api//double//slash/",
	"",
	"/",
	"/api/notes#only-fragment",
];
write("route-shape.json", paths.map((path) => [path, routeShape(path)]));

// ----------------------------------------------------- noteDocumentToMarkdown
const text = (value, marks) => (marks ? { type: "text", text: value, marks } : { type: "text", text: value });
const p = (...content) => ({ type: "paragraph", content });
const h = (level, ...content) => ({ type: "heading", attrs: { level }, content });
const doc = (...content) => ({ type: "doc", content });
const li = (...content) => ({ type: "listItem", content });

const markdownCases = [
	["simple", "My Study", doc(p(text("In the beginning God created the heaven and the earth.")))],
	["empty doc", "Empty", doc()],
	["empty title", "   ", doc(p(text("Body")))],
	["duplicate h1 title is dropped", "Romans Road", doc(h(1, text("romans road ")), p(text("Body")))],
	["h1 that differs is kept", "Romans Road", doc(h(1, text("Another")), p(text("Body")))],
	["h2 matching title is kept", "Same", doc(h(2, text("Same")))],
	["heading levels", "H", doc(h(2, text("Two")), h(6, text("Six")), h(9, text("Nine")), { type: "heading", content: [text("None")] }, h("3", text("String three")), h(0, text("Zero")))],
	[
		"marks",
		"Marks",
		doc(
			p(
				text("bold", [{ type: "bold" }]),
				text(" "),
				text("italic", [{ type: "italic" }]),
				text(" "),
				text("strike", [{ type: "strike" }]),
				text(" "),
				text("under", [{ type: "underline" }]),
				text(" "),
				text("lit", [{ type: "highlight" }]),
				text(" "),
				text("both", [{ type: "bold" }, { type: "italic" }])
			)
		),
	],
	["code marks", "Code", doc(p(text("plain *x*"), text("a `tick` and `` two", [{ type: "code" }]), text("no ticks", [{ type: "code" }])))],
	[
		"links",
		"Links",
		doc(
			p(
				text("site", [{ type: "link", attrs: { href: "https://sureword.app/a b(c)\\d" } }]),
				text(" "),
				text("bare", [{ type: "link", attrs: {} }]),
				text(" "),
				text("bold link", [{ type: "link", attrs: { href: "https://x.test" } }, { type: "bold" }])
			)
		),
	],
	["escaping", "Esc", doc(p(text("a*b_c`d[e]f<g>h\\i")), p(text("# not a heading")), p(text("- not a list")), p(text("  + plus")), p(text("1. not ordered")), p(text("2) paren")), p(text("3.no space")), p(text("= equals ~ tilde")))],
	["multiline escaping", "Lines", doc(p(text("line one\n- dash\n12. twelve")))],
	["wikilinks kept", "Wiki", doc(p(text("See [[Romans 8]] and [[Grace_notes*]] but not [single] or [[broken")))],
	["hard break", "Break", doc(p(text("first"), { type: "hardBreak" }, text("second")))],
	["blockquote", "Quote", doc({ type: "blockquote", content: [p(text("Verse line")), p(text("Second para"))] })],
	["bullet list", "List", doc({ type: "bulletList", content: [li(p(text("one"))), li(p(text("two")), p(text("two b")))] })],
	["ordered list start", "Ordered", doc({ type: "orderedList", attrs: { start: 3 }, content: [li(p(text("three"))), li(p(text("four")))] })],
	["ordered list no start", "Ordered", doc({ type: "orderedList", content: [li(p(text("one")))] })],
	["ordered list null start", "Ordered", doc({ type: "orderedList", attrs: { start: null }, content: [li(p(text("one")))] })],
	[
		"task list",
		"Tasks",
		doc({
			type: "taskList",
			content: [
				{ type: "taskItem", attrs: { checked: true }, content: [p(text("done"))] },
				{ type: "taskItem", attrs: { checked: false }, content: [p(text("todo"))] },
				{ type: "taskItem", content: [p(text("no attrs"))] },
			],
		}),
	],
	[
		"nested list",
		"Nested",
		doc({ type: "bulletList", content: [li(p(text("outer")), { type: "orderedList", attrs: { start: 1 }, content: [li(p(text("inner")))] })] }),
	],
	["list in quote", "QL", doc({ type: "blockquote", content: [{ type: "bulletList", content: [li(p(text("a"))), li(p(text("b")))] }] })],
	["code block", "Block", doc({ type: "codeBlock", attrs: { language: "swift" }, content: [text("let x = 1\nprint(x)")] })],
	["code block ticks", "Block", doc({ type: "codeBlock", attrs: { language: "js;rm -rf" }, content: [text("a ```` b")] })],
	["code block empty", "Block", doc({ type: "codeBlock", attrs: { language: null } })],
	["rule", "Rule", doc(p(text("above")), { type: "horizontalRule" }, p(text("below")))],
	["empty paragraphs", "Gaps", doc(p(text("a")), p(), p(text("b")))],
	["unicode", "Grâce ✝", doc(p(text("“Jesus wept.” - John 11:35 ✝ 🙏")))],
	["unknown node", "Bad", doc(p(text("ok")), { type: "image", attrs: { src: "x" } })],
	["unknown mark", "Bad", doc(p(text("sup", [{ type: "superscript" }])))],
	["invalid list item", "Bad", doc({ type: "bulletList", content: [p(text("not an item"))] })],
	["inline non-text", "Bad", doc(p({ type: "mention", attrs: { id: "x" } }))],
	["not a doc", "Bad", { type: "paragraph", content: [] }],
	["missing content", "Bad", { type: "doc" }],
];
write(
	"note-markdown.json",
	markdownCases.map(([name, title, document]) => {
		try {
			return { name, title, document, markdown: noteDocumentToMarkdown(title, document) };
		} catch (error) {
			return { name, title, document, error: error.message };
		}
	})
);

// --------------------------------------------------------- buildNoteTemplate
// A Wednesday and a Sunday, so the sermon template's "back to Sunday" is
// exercised both ways.
const dates = ["2026-10-07T15:30:00.000Z", "2026-10-04T00:00:00.000Z"];
const templateCases = [];
for (const iso of dates) {
	for (const id of ["verse-study", "sermon", "prayer", "blank"]) {
		templateCases.push({ id, now: iso, churchName: null, seed: buildNoteTemplate(id, { now: new Date(iso) }) });
	}
	templateCases.push({ id: "sermon", now: iso, churchName: "  Grace & Truth \"Bible\" Church  ", seed: buildNoteTemplate("sermon", { now: new Date(iso), churchName: "  Grace & Truth \"Bible\" Church  " }) });
	templateCases.push({ id: "sermon", now: iso, churchName: "   ", seed: buildNoteTemplate("sermon", { now: new Date(iso), churchName: "   " }) });
}
write("note-templates.json", templateCases);

console.log(`wrote ${paths.length} route shapes, ${markdownCases.length} markdown cases, ${templateCases.length} templates to ${out}`);
